    expect((response._meta as any)?.jetbrains?.air?.sessionFailure).toBeUndefined();
    await expect(
      agent.prompt({
        sessionId: "test-session",
        prompt: [{ type: "text", text: "continue" }],
      }),
    ).rejects.toThrow("session has ended");
